                {"code": "AGR.4", "name": "Carbon Sequestration (Agroforestry)", "formula": "C_seq = (tree_biomass × 0.5 + soil_C_gain) × area × years", "variables": "tree_biomass = t DM/ha/yr\n0.5 = carbon fraction of biomass\nsoil_C_gain = t C/ha/yr from leaf litter + roots", "purpose": "Estimate total carbon sequestration from agroforestry. Higher than monoculture — qualifies for carbon credits.", "example": "Leucaena 8 t DM/ha/yr, soil gain 0.5 t C: C_seq = (8×0.5 + 0.5) = 4.5 t C/ha/yr = 16.5 t CO₂e/ha/yr.", "pitfall": "Tree harvest releases stored C. Long-term C requires permanent trees + regrowth.", "decision": "Choose fast-growing N-fixing trees (Leucaena, Gliricidia) for max C + N.", "notes": "IPCC 2006. Agroforestry C rates: 2-10 t CO₂e/ha/yr depending on system.", "name_ar": "عزل الكربون في الحراج الزراعي", "purpose_ar": "تقدير إجمالي الكربون المختزن.", "variables_ar": "tree_biomass = الكتلة الحيوية"},
                {"code": "AGR.5", "name": "Fodder Tree Carrying Capacity", "formula": "CC = (biomass × utilization × protein) / (intake × protein_req × grazing_days)", "variables": "biomass = edible DM production (kg/ha)\nutilization = safe utilization rate (0.5-0.7)\nintake = 3% BW (kg DM/day)\nprotein_req = protein requirement (g/day)", "purpose": "Estimate livestock carrying capacity for fodder trees (Leucaena, Acacia). Enables rotational browsing.", "example": "Leucaena produces 4000 kg DM/ha, 25% protein. 400 kg cow, 3% BW = 12 kg/day: CC = (4000×0.6×0.25)/(12×0.12×180) = 2.3 cows/ha for 6 months.", "pitfall": "Some fodder trees contain anti-nutritional factors (mimosine in Leucaena). Limit to 30% of diet.", "decision": "Supplement with grass — trees provide protein, grass provides energy.", "notes": "Gutteridge & Shelton (1994). Leucaena + grass pasture = 2× carrying capacity of grass alone.", "name_ar": "السعة الاستيعابية لأشجار العلف", "purpose_ar": "تقدير السعة لرعي المواشي على أشجار العلف.", "variables_ar": "biomass = الإنتاج الصالح للأكل"},
                {"code": "AGR.6", "name": "Shade Effect on Understory Yield", "formula": "Y_loss = shade% × crop_sensitivity", "variables": "shade% = percent light reduction (0-1)\ncrop_sensitivity = 0.3 (tolerant) to 1.2 (sensitive)", "purpose": "Predict yield loss of understory crop due to tree shade. Shade-tolerant crops (coffee, cacao) lose less than cereals.", "example": "Maize under 30% shade, sensitivity 1.0: Y_loss = 0.30 × 1.0 = 30% yield reduction. Coffee under 30% shade, sensitivity 0.2: 6% loss — shade beneficial (reduces heat stress).", "pitfall": "Some crops benefit from shade in hot climates. Shade reduces temperature + evapotranspiration.", "decision": "Match crop to shade level. Coffee: 30-50% shade. Maize: 0-10%. Choose shade-tolerant varieties.", "notes": "Mead & Willey (1980). Light × water × nutrient interactions are complex — test locally.", "name_ar": "تأثير الظل على إنتاج المحصول", "purpose_ar": "التنبؤ بخسارة إنتاج المحصول بسبب ظل الأشجار.", "variables_ar": "shade% = نسبة تقليل الضوء"},
