                {"code": "PB.2", "name": "Narrow-Sense Heritability (h²)", "formula": "h² = Va / Vp = Va / (Va + Vd + Vi + Ve)", "variables": "Va = additive genetic variance\nVd = dominance variance\nVi = epistatic variance\nVe = environmental variance", "purpose": "Estimate proportion of variation that is heritable + fixable by selection. h² determines response to selection — more actionable than H².", "example": "Maize yield: Va=0.8, Vd=0.3, Vi=0.1, Ve=1.3: h² = 0.8/2.5 = 0.32. Selection will capture 32% of observed variation.", "pitfall": "h² ≤ H² always. h² can be estimated from parent-offspring regression: h² = 2 × slope (half-sib) or 1 × slope (full-sib).", "decision": "Select for traits with h² >0.3 for reliable improvement. Below 0.15: use indirect selection or markers.", "notes": "Falconer & Mackay (1996). h² is the key parameter for breeder's equation.", "name_ar": "قابلية التوريث الضيقة", "purpose_ar": "تقدير الجزء القابل للتوريث والثابت بالانتخاب.", "variables_ar": "Va = التباين المضاف"},
                {"code": "PB.3", "name": "Response to Selection (Breeder's Equation)", "formula": "R = h² × S", "variables": "R = response (change in mean per generation)\nh² = narrow-sense heritability\nS = selection differential (selected mean − population mean)", "purpose": "Predict genetic gain per generation. Core equation of plant breeding. Higher h² or stronger selection → more gain.", "example": "Wheat protein, h²=0.4, select top 20% (S=3% above mean): R = 0.4 × 3 = 1.2% gain per generation. 5 generations → 6% increase.", "pitfall": "S decreases as selection intensity increases (fewer selected). Genetic variance is depleted over cycles.", "decision": "Balance selection intensity (S) with genetic diversity (avoid inbreeding).", "notes": "Lush (1937). Called 'realized heritability' when computed from actual response: h² = R/S.", "name_ar": "الاستجابة للانتخاب (معادلة المربي)", "purpose_ar": "التنبؤ بالكسب الوراثي لكل جيل.", "variables_ar": "R = الاستجابة\nh² = القابلية\nS = التفاضل الانتخابي"},
                {"code": "PB.4", "name": "Genetic Gain per Cycle", "formula": "ΔG = (i × h² × σp) / L", "variables": "i = selection intensity (1.4 for 20% selected, 2.1 for 5%)\nh² = narrow-sense heritability\nσp = phenotypic standard deviation\nL = length of breeding cycle (years)", "purpose": "Annual genetic gain — accounts for cycle time. Fast-cycling crops (1 yr) can gain 10× more per year than trees (10 yr cycle).", "example": "Wheat: i=1.4 (top 20%), h²=0.3, σp=0.5 t/ha, L=4 yr: ΔG = (1.4×0.3×0.5)/4 = 0.053 t/ha/yr = 53 kg/ha/yr.", "pitfall": "Speed breeding (off-season nurseries + greenhouse) reduces L → faster gain.", "decision": "Invest in reducing L: shuttle breeding, speed breeding, genomic selection.", "notes": "Eberhart (1970). Annual gain = ΔG. Compare crops: maize ~1%/yr, wheat ~0.5%, trees ~0.1%.", "name_ar": "الكسب الوراثي لكل دورة", "purpose_ar": "الكسب الوراثي السنوي.", "variables_ar": "i = شدة الانتخاب\nσp = الانحراف المعياري"},
